(()=>{
 const $=id=>document.getElementById(id),node=(tag,text,cls='')=>{const e=document.createElement(tag);e.textContent=text;if(cls)e.className=cls;return e;};
 async function api(path,options={}){const r=await fetch(path,{...options,headers:{'Content-Type':'application/json',...(options.headers||{})},signal:AbortSignal.timeout(20000)});let d;try{d=await r.json();}catch{throw Error('The server returned an unreadable response.');}if(!r.ok)throw Error(d.error||'Request failed.');return d;}
 function show(loggedIn){$('login-panel').hidden=loggedIn;$('records-panel').hidden=!loggedIn;$('logout').hidden=!loggedIn;if(loggedIn)load();}
 function empty(target,text){target.replaceChildren(node('p',text,'admin-empty'));}
 async function load(){const status=$('records-status');status.textContent='Loading Supabase records…';$('refresh').disabled=true;try{const [d,n,l]=await Promise.all(['donations','notifications','lapsed'].map(resource=>api('/api/admin-records?resource='+resource)));const body=$('donations');body.replaceChildren();for(const x of d.records||[]){const row=node('tr','');for(const value of [x.donated_on,x.donor,`${x.currency||'INR'} ${Number(x.amount).toFixed(2)}`,x.mode,x.receipt_no,x.receipt_sent?'Sent':'Pending',x.thank_you_sent?'Sent':'Pending'])row.append(node('td',value));body.append(row);}if(!body.children.length){const row=node('tr','');const cell=node('td','No donations recorded in this workspace.','admin-empty');cell.colSpan=7;row.append(cell);body.append(row);}const notifications=$('notifications');notifications.replaceChildren();for(const x of n.records||[])notifications.append(node('p',`${x.document_type==='receipt'?'Receipt + thank-you':'Donor report'} · ${x.channel} · ${x.status} · ${new Date(x.created_at).toLocaleString()}`));if(!notifications.children.length)empty(notifications,'No delivery activity recorded.');const lapsed=$('lapsed');lapsed.replaceChildren();for(const x of l.donors||[])lapsed.append(node('p',`${x.donor} · Last donation: ${x.donated_on}`));if(!lapsed.children.length)empty(lapsed,'No inactive donors found.');status.textContent=`Loaded ${(d.records||[]).length} donations and ${(n.records||[]).length} delivery records from Supabase.`;}catch(e){status.textContent=e.message;if(/login/i.test(e.message))show(false);}finally{$('refresh').disabled=false;}}
 $('login-form').onsubmit=async e=>{e.preventDefault();$('login-status').textContent='Checking access…';try{await api('/api/admin-session',{method:'POST',body:JSON.stringify({password:$('admin-password').value})});$('admin-password').value='';$('login-status').textContent='';show(true);}catch(err){$('login-status').textContent=err.message;}};
 $('logout').onclick=async()=>{await api('/api/admin-session',{method:'DELETE'});show(false);};$('refresh').onclick=load;
 api('/api/admin-session').then(s=>show(s.authenticated)).catch(()=>show(false));
})();